+/// `--upstream` never forwards a request (or its bearer) meant for this site.
+/// `/api/v1/` is the inference API, which goes upstream unless an inference
+/// service is configured.
+#[test]
+fn every_mounted_route_is_owned() {
+    fn sources(dir: &std::path::Path, out: &mut Vec<PathBuf>) {
+        for entry in std::fs::read_dir(dir).unwrap() {
+            let path = entry.unwrap().path();
+            if path.is_dir() {
+                sources(&path, out);
+            } else if path.extension().is_some_and(|ext| ext == "rs") {
+                out.push(path);
+            }
+        }
+    }
+    let mut files = Vec::new();
+    sources(
+        &std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("src"),
+        &mut files,
+    );
+    let mut checked = 0;
+    for file in files {
+        let text = std::fs::read_to_string(&file).unwrap();
+        for piece in text.split(".route(\"").skip(1) {
+            let route = &piece[..piece.find('"').unwrap()];
+            if route.starts_with("/api/v1/") {
+                continue;
+            }
+            // `{param}` and `{*rest}` become a sample segment.
+            let mut path = String::new();
+            for segment in route.split('/').skip(1) {
+                path.push('/');
+                path.push_str(if segment.starts_with('{') {
+                    "x"
+                } else {
+                    segment
+                });
+            }
+            assert!(
+                upstream::owned(&path),
+                "{} mounts {route}",
+                file.display()
+            );
+            checked += 1;
+        }
+    }
+    assert!(checked > 50, "{checked}");
+    for path in ["/coder/sessions", "/coder/sync", "/coder/check-in"] {
+        assert!(upstream::owned(path), "{path}");
+    }
+}
